export default {
  name: "AddTransaction",
  props: {
    transactionAdd: {
      type: Boolean,
      default: false
    },
    transactionType: {
      type: String,
      default: "expense"
    }
  },
  data() {
    return {
      isFormValid: false,
      submitting: false,
      validationError: "",
      // Form fields
      amount: "",
      description: "",
      category: "",
      pettyCashType: "",
      attachments: [],
      // Options
      transactionTypes: [{
        title: "Expense",
        value: "expense"
      }, {
        title: "Petty Cash",
        value: "pettycash"
      }],
      expenseCategories: ["Office Supplies", "Travel", "Meals", "Transportation", "Utilities", "Other"],
      pettyCashTypes: [{
        title: "Withdrawal",
        value: "DEBIT"
      }, {
        title: "Deposit",
        value: "CREDIT"
      }],
      // Validation rules
      amountRules: [v => !!v || "Amount is required", v => !isNaN(v) || "Must be a valid number", v => parseFloat(v) > 0 || "Amount must be greater than 0", v => parseFloat(v) <= 999999 || "Amount too large"],
      fileRules: [v => !v || v.length <= 5 || "Maximum 5 files allowed"]
    };
  },
  watch: {
    transactionType(newVal) {
      // Reset form when transaction type changes
      this.resetForm();
    }
  },
  methods: {
    validateAmount() {
      const amount = parseFloat(this.amount);
      if (this.amount && (isNaN(amount) || amount <= 0)) {
        this.validationError = "Please enter a valid positive amount";
      } else {
        this.validationError = "";
      }
    },
    resetForm() {
      this.amount = "";
      this.description = "";
      this.category = "";
      this.pettyCashType = "";
      this.attachments = [];
      this.validationError = "";
      this.$refs.form?.resetValidation();
    },
    closeDialog() {
      this.resetForm();
      this.$emit("clicked");
    },
    async submitTransaction() {
      if (!this.isFormValid) {
        this.validationError = "Please fix validation errors before submitting";
        return;
      }
      this.submitting = true;
      try {
        // Prepare transaction data
        const transactionData = {
          type: this.transactionType,
          amount: parseFloat(this.amount),
          description: this.description,
          category: this.transactionType === "expense" ? this.category : null,
          pettyCashType: this.transactionType === "pettycash" ? this.pettyCashType : null,
          attachments: this.attachments,
          timestamp: new Date().toISOString()
        };

        // console.log("Submitting transaction:", transactionData);

        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 1000));

        // Emit success event
        this.$emit("successMsg", `${this.transactionType === "expense" ? "Expense" : "Petty cash"} submitted successfully!`);

        // Close dialog
        this.closeDialog();
      } catch (error) {
        console.error("Error submitting transaction:", error);
        this.$emit("errorMsg", "Failed to submit transaction. Please try again.");
      } finally {
        this.submitting = false;
      }
    }
  }
};
